    "HA-M-000004": [
      {
        "actionKey": "motion-option-003",
        "learnerActionKey": null,
        "label": "발 안쪽번짐",
        "text": {
          "label": "발 안쪽번짐",
          "explanation": "해당 근육은 발 안쪽번짐에 관여합니다. 이 요약은 해당 작용을 다룬 출처에 한정되며, 이 근육 하나가 움직임 전체를 단독으로 만든다는 뜻은 아닙니다.",
          "postureConditions": [
            "문헌의 검사 예시: 반듯이 누워 발목을 약간 발바닥굽힘 위치에 둔 자세."
          ],
          "stabilizationConditions": [],
          "stabilizationNote": "문헌의 자세 설정과 검사자 손/지지면은 검사 방법으로만 남겼습니다. 이를 이 근육이 고정하는 해부학적 구조나 일반 안정화 작용으로 바꾸지 않았습니다.",
          "contextNotes": [
            {
              "label": "출처에서 확인한 맥락",
              "explanation": "이 문헌은 해당 근육을 발 안쪽번짐 검사에서 주 검사 근육으로 지정합니다. 이는 검사 맥락의 지정이며, 일반 움직임에서 작용근·협력근 역할이나 기여 비중을 따로 분류하지 않습니다."
            },
            {
              "label": "출처가 설명한 지지 역할",
              "explanation": "문헌은 뒤정강근이 발목 발바닥굽힘에 기여하고 중간발 안쪽번짐과 안쪽세로발바닥활 지지에 관여한다고 설명합니다. 보행 중 중간입각기의 중간발 엎침 조절도 언급합니다."
            },
            {
              "label": "출처에서 확인한 맥락",
              "explanation": "표는 뒤정강근에 발 모음·발바닥굽힘과 회외 보조도 적습니다."
            }
          ],
          "contractionNote": "조사한 자료는 개별 근육의 수축 종류를 따로 구분하지 않았습니다.",
          "citations": []
        },
        "sideApplicability": "bilateral",
        "candidate": null
      }
    ],
